const payload = $input.first().json || {};
const risk = payload.snapshot || {};
let message = '📚 *Regulatory Ingestion Weekly Check*\n\n';
message += `Assessment ID: ${payload.assessment_id || 'n/a'}\n`;
message += `🛡 Risk score: ${risk.risk_score ?? 'n/a'} (${risk.risk_level || 'unknown'})\n`;
message += `Signals — rules: ${risk.signals?.active_rules ?? 0}, med logs today: ${risk.signals?.medication_logs_today ?? 0}, sanitation today: ${risk.signals?.sanitation_checks_today ?? 0}, sleep checks today: ${risk.signals?.sleep_safety_checks_today ?? 0}`;
return [{json: {message}}];
